### Add Streaming (20 minutes)

```tsx
// app/api/chat/route.ts
export async function POST(request: Request) {
  const { messages } = await request.json()

  const stream = await openai.chat.completions.create({
    model: 'gpt-4',
    messages,
    stream: true,
  })

  const encoder = new TextEncoder()

  return new Response(
    new ReadableStream({
      async start(controller) {
        for await (const chunk of stream) {
          const text = chunk.choices[0]?.delta?.content || ''
          controller.enqueue(encoder.encode(`data: ${text}\n\n`))
        }
        controller.close()
      },
    }),
    {
      headers: {
        'Content-Type': 'text/event-stream',
        'Cache-Control': 'no-cache',
        Connection: 'keep-alive',
      },
    }
  )
}
```

Update component to use streaming:

```tsx
import { useStreaming } from '@clarity-chat/react'

const { streamMessage, isStreaming } = useStreaming()

const handleSendMessage = async (content: string) => {
  const userMessage = {
    id: Date.now().toString(),
    role: 'user' as const,
    content,
    timestamp: new Date(),
  }
  setMessages((prev) => [...prev, userMessage])

  const aiMessage = {
    id: (Date.now() + 1).toString(),
    role: 'assistant' as const,
    content: '',
    timestamp: new Date(),
  }
  setMessages((prev) => [...prev, aiMessage])

  await streamMessage('/api/chat', {
    method: 'POST',
    body: JSON.stringify({ messages: [...messages, userMessage] }),
    onChunk: (text) => {
      setMessages((prev) =>
        prev.map((m) => (m.id === aiMessage.id ? { ...m, content: m.content + text } : m))
      )
    },
  })
}
```

