async function handleToolCall(toolCall: ToolCall) {
  // Execute tool
  const result = await orchestrator.executeTool(
    toolCall.toolName,
    toolCall.args
  )

  // Summarize if large
  const summarizedResult = await summarizeToolResult(
    toolCall.toolName,
    result.result
