    role: 'assistant',
    content: '',
    toolInvocations: [{
      state: 'result',
      toolCallId: toolCall.id,
      toolName: toolCall.toolName,
      args: toolCall.args,
      result: summarizedResult
    }]
  }

  await addToMemory(memoryState, message, {
    storage: 'indexeddb',
    scope: 'thread'
