      <div>
        <Input
          type="email"
          value={email}
          onChange={(e) => {
            setEmail(e.target.value)
            if (error) validateEmail(e.target.value)
          }}
          onBlur={() => validateEmail(email)}
          placeholder="Enter your email"
          variant={error ? 'error' : 'default'}
