## Type Guards

The error-handling package provides comprehensive type guards:

```typescript
import {
  isNetworkError,
  isRateLimitError,
  isAuthError,
  isRecoverableError,
  hasRetryAfter,
  hasPartialContent,
  getErrorStatusCode,
  getErrorCode,
  getUserMessage,
  normalizeError,
} from '@clarity-chat/error-handling'

// Network error detection
if (isNetworkError(error)) {
  showConnectivityWarning()
}

// Rate limit handling with Retry-After
if (isRateLimitError(error) && hasRetryAfter(error)) {
  const retryAfter = error.retryAfter // seconds
  showRateLimitMessage(retryAfter)
}

// Authentication errors
if (isAuthError(error)) {
  redirectToLogin()
}

// Recoverable errors
if (isRecoverableError(error)) {
  showRetryButton()
}

// Extract status code safely
const statusCode = getErrorStatusCode(error) // number | undefined

// Extract error code safely
const errorCode = getErrorCode(error) // string | undefined

// Get user-friendly message
const message = getUserMessage(error) // string

// Normalize any error to Error object
const normalized = normalizeError(error) // always returns Error
```

