**Purpose:** Validate array with length constraints and item validation

**Usage:**
```typescript
validateArray<T>(
  value: unknown,
  itemValidator: (item: unknown) => item is T,
  options?: {
    minLength?: number
    maxLength?: number
    required?: boolean
  }
): StrictValidation<T[]>
```

**Example:**
```typescript
// Validate string array
const tagsResult = validateArray(tags, isString, {
  minLength: 1,
  maxLength: 10,
})

if (!tagsResult.success) {
  console.error(tagsResult.errors)
  // ["Array must have at least 1 items"]
  // ["Item at index 2 is invalid"]
} else {
  saveTags(tagsResult.data) // string[]
}

// Custom validator
const isPositiveNumber = (v: unknown): v is number =>
  isNumber(v) && v > 0

const scoresResult = validateArray(scores, isPositiveNumber, {
  minLength: 1,
})
```

