### validateUnion()

**Purpose:** Validate value against multiple possible types

**Usage:**
```typescript
validateUnion<T extends readonly unknown[]>(
  value: unknown,
  validators: readonly [...{ [K in keyof T]: (value: unknown) => value is T[K] }]
): StrictValidation<T[number]>
```

**Example:**
```typescript
// string | number union
const result = validateUnion(value, [isString, isNumber] as const)

if (result.success) {
  // result.data is string | number
}

// Complex union
const isUser = (v: unknown): v is User => isObject(v) && isString(v.id)
const isAdmin = (v: unknown): v is Admin => isObject(v) && v.role === 'admin'

const userResult = validateUnion(data, [isUser, isAdmin] as const)
