### assertDefined()

**Purpose:** Assert value is not null/undefined, throw if not

**Usage:**
```typescript
assertDefined<T>(
  value: T | null | undefined,
  message?: string
): asserts value is T
```

**Example:**
```typescript
function getUserName(userId: string): string {
  const user = findUser(userId) // User | undefined
  assertDefined(user, `User ${userId} not found`)
  // user is now User (non-nullable)
  return user.name
}

// API response validation
interface ApiResponse {
  data?: { id: string }
}

function handleResponse(response: ApiResponse) {
  assertDefined(response.data, 'API response missing data')
  // response.data is now guaranteed defined
  processData(response.data.id)
}
```

