### assertNever()

**Purpose:** Exhaustive checking in switch statements

**Usage:**
```typescript
assertNever(value: never, message?: string): never
```

**Example:**
```typescript
type Action = 'create' | 'update' | 'delete'

function handleAction(action: Action) {
  switch (action) {
    case 'create':
      return createItem()
    case 'update':
      return updateItem()
    case 'delete':
      return deleteItem()
    default:
      // TypeScript error if new action added but not handled
      return assertNever(action, `Unknown action: ${action}`)
  }
}
```

