### Complete Streaming Flow

```tsx
import { 
  openAIAdapter, 
  StreamingMessage, 
  ToolInvocationCard, 
  CitationCard,
  ModelSelector,
  allModels
} from '@clarity-chat/react'

function Chat() {
  const [model, setModel] = useState('gpt-4-turbo')
  const [content, setContent] = useState('')
  const [isStreaming, setIsStreaming] = useState(false)
  const [toolCalls, setToolCalls] = useState([])
  const [citations, setCitations] = useState([])
  const [toolStatuses, setToolStatuses] = useState({})

  const handleStream = async () => {
    setContent('')
    setIsStreaming(true)

    const config = {
      provider: 'openai',
      model,
      apiKey: process.env.OPENAI_API_KEY
    }

    try {
      for await (const chunk of openAIAdapter.stream(messages, config)) {
        switch (chunk.type) {
          case 'token':
            setContent(prev => prev + chunk.content)
            break
          case 'tool_call':
            setToolCalls(prev => [...prev, chunk.toolCall])
            setToolStatuses(prev => ({ ...prev, [chunk.toolCall.id]: 'pending' }))
            break
          case 'citation':
            setCitations(prev => [...prev, chunk.citation])
            break
        }
      }
    } finally {
      setIsStreaming(false)
    }
  }

  const handleApprove = async (tool) => {
    setToolStatuses(prev => ({ ...prev, [tool.id]: 'executing' }))
    try {
      await executeTool(tool)
      setToolStatuses(prev => ({ ...prev, [tool.id]: 'success' }))
    } catch {
      setToolStatuses(prev => ({ ...prev, [tool.id]: 'error' }))
    }
  }

  return (
    <div>
      <ModelSelector
        models={allModels}
        value={model}
        onChange={(id) => setModel(id)}
      />

      <StreamingMessage
        content={content}
        isStreaming={isStreaming}
      />

      {toolCalls.map(tool => (
        <ToolInvocationCard
          key={tool.id}
          toolCall={tool}
          status={toolStatuses[tool.id]}
          requiresApproval
          onApprove={handleApprove}
        />
      ))}

      {citations.map(citation => (
        <CitationCard
          key={citation.id}
          citation={citation}
          showConfidence
        />
      ))}
    </div>
  )
}
```

