## Complete Example

```tsx
import {
  ChatWindow,
  PromptTemplateLibrary,
  PromptTemplateEngine,
  builtInPrompts,
} from '@clarity-chat/react'

function AdvancedChatWithPrompts() {
  const [messages, setMessages] = useState([])
  const library = new PromptTemplateLibrary()
  const engine = new PromptTemplateEngine()

  useEffect(() => {
    // Initialize library with built-in prompts
    Object.values(builtInPrompts).forEach(template => {
      library.add(template)
    })

    // Add custom templates
    library.add({
      id: 'customer-support',
      name: 'Customer Support',
      template: `You are a helpful customer support agent.

Customer question: {{question}}
Customer context: {{context}}

Please provide a helpful and friendly response.`,
      variables: [
        { name: 'question', type: 'string', required: true },
        { name: 'context', type: 'string', required: false },
      ],
      tags: ['support', 'customer'],
    })
  }, [])

  const handleSend = async (content: string) => {
    // Get template
    const template = library.get('customer-support')
    if (!template) return

    // Render prompt
    const result = engine.render(template, {
      variables: {
        question: content,
        context: 'Premium customer',
      },
      validate: true,
    })

    if (!result.success) {
      console.error(result.errors)
      return
    }

    // Use rendered prompt
    const response = await fetch('/api/chat', {
      method: 'POST',
      body: JSON.stringify({
        messages: [
          { role: 'system', content: result.prompt },
          { role: 'user', content },
        ],
      }),
    })

    const data = await response.json()
    setMessages(prev => [...prev, {
      id: data.id,
      role: 'assistant',
      content: data.message,
      timestamp: Date.now(),
    }])
  }

  return (
    <ChatWindow
      messages={messages}
      onSendMessage={handleSend}
    />
  )
}
```

## Step 3: Create Chat Component

Create `components/Chat.tsx`:

```tsx
'use client' // Next.js App Router only

import { ChatWindow } from '@clarity-chat/react'
import type { Message } from '@clarity-chat/types'
import { useState } from 'react'

export function Chat() {
  const [messages, setMessages] = useState<Message[]>([
    {
      id: '1',
      role: 'assistant',
      content: 'Hello! How can I help you today?',
      timestamp: Date.now(),
    },
  ])
  const [isLoading, setIsLoading] = useState(false)

  const handleSendMessage = async (content: string) => {
    // Add user message
    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content,
      timestamp: Date.now(),
    }
    setMessages((prev) => [...prev, userMessage])
    setIsLoading(true)

    try {
      // Call your AI API
      const response = await fetch('/api/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          messages: [...messages, userMessage],
        }),
      })

      const data = await response.json()

      // Add AI response
      setMessages((prev) => [
        ...prev,
        {
          id: (Date.now() + 1).toString(),
          role: 'assistant',
          content: data.message,
          timestamp: Date.now(),
        },
      ])
    } catch (error) {
      console.error('Failed to send message:', error)
      // Add error message
      setMessages((prev) => [
        ...prev,
        {
          id: (Date.now() + 1).toString(),
          role: 'assistant',
          content: 'Sorry, I encountered an error. Please try again.',
          timestamp: Date.now(),
          error: true,
        },
      ])
    } finally {
      setIsLoading(false)
    }
  }

  return (
    <div style={{ width: '100%', maxWidth: '800px', height: '600px' }}>
      <ChatWindow messages={messages} isLoading={isLoading} onSendMessage={handleSendMessage} />
    </div>
  )
}
```

