### Step 1: Define Tools

Create `lib/tools.ts`:

```typescript
import type { Tool } from '@clarity-chat/react'

export const searchTool: Tool = {
  name: 'search',
  description: 'Search the web for information',
  parameters: {
    type: 'object',
    properties: {
      query: {
        type: 'string',
        description: 'Search query',
      },
    },
    required: ['query'],
  },
  execute: async ({ query }) => {
    // Implement your search logic
    const results = await fetch(`https://api.example.com/search?q=${query}`)
    return await results.json()
  },
}

export const calculatorTool: Tool = {
  name: 'calculator',
  description: 'Perform mathematical calculations',
  parameters: {
    type: 'object',
    properties: {
      expression: {
        type: 'string',
        description: 'Mathematical expression to evaluate',
      },
    },
    required: ['expression'],
  },
  execute: async ({ expression }) => {
    try {
      // Safe evaluation (use a proper math parser in production)
      const result = Function(`"use strict"; return (${expression})`)()
      return { result }
    } catch (error) {
      return { error: 'Invalid expression' }
    }
  },
}
```

### Step 3: Create Agent API Route

Create `app/api/agent/route.ts`:

```typescript
import { NextRequest, NextResponse } from 'next/server'
import { agent } from '@/lib/agent'

export async function POST(request: NextRequest) {
  try {
    const { message } = await request.json()

    const result = await agent.run({
      input: message,
    })

    return NextResponse.json({
      output: result.output,
      toolCalls: result.toolCalls,
    })
  } catch (error: any) {
    return NextResponse.json(
      { error: error.message },
      { status: 500 }
    )
  }
}
```

