## Integration with Chat

Emit events from chat operations:

```tsx
import { ChatWindow, WebhookManager, WebhookEvents } from '@clarity-chat/react'

function ChatWithWebhooks() {
  const [messages, setMessages] = useState([])
  const webhooks = new WebhookManager()

  useEffect(() => {
    // Register webhook endpoint
    webhooks.register({
      id: 'chat-analytics',
      url: '/api/webhooks/analytics',
      events: [WebhookEvents.CHAT_MESSAGE_SENT, WebhookEvents.CHAT_COMPLETION],
    })
  }, [])

  const handleSend = async (content: string) => {
    const messageId = Date.now().toString()

    // Add user message
    setMessages(prev => [...prev, {
      id: messageId,
      role: 'user',
      content,
      timestamp: Date.now(),
    }])

    // Emit webhook event
    await webhooks.emit({
      id: `evt-${messageId}`,
      type: WebhookEvents.CHAT_MESSAGE_SENT,
      data: {
        messageId,
        content,
        userId: 'user-123',
      },
      timestamp: Date.now(),
    })

    // Get AI response...
    const response = await fetch('/api/chat', {
      method: 'POST',
      body: JSON.stringify({ message: content }),
    })

    const data = await response.json()

    // Emit completion event
    await webhooks.emit({
      id: `evt-${Date.now()}`,
      type: WebhookEvents.CHAT_COMPLETION,
      data: {
        messageId: data.id,
        tokens: data.tokens,
        model: data.model,
      },
      timestamp: Date.now(),
    })
  }

  return (
    <ChatWindow
      messages={messages}
      onSendMessage={handleSend}
    />
  )
}
```

