## Complete Example

```tsx
import {
  ChatWindow,
  WebhookManager,
  WebhookEvents,
} from '@clarity-chat/react'

function ChatAppWithWebhooks() {
  const [messages, setMessages] = useState([])
  const webhooks = new WebhookManager({
    maxRetries: 3,
    timeout: 5000,
  })

  useEffect(() => {
    // Register analytics webhook
    webhooks.register({
      id: 'analytics',
      url: '/api/webhooks/analytics',
      events: [
        WebhookEvents.CHAT_MESSAGE_SENT,
        WebhookEvents.CHAT_COMPLETION,
      ],
      secret: process.env.WEBHOOK_SECRET,
    })

    // Register monitoring webhook
    webhooks.register({
      id: 'monitoring',
      url: '/api/webhooks/monitoring',
      events: [
        WebhookEvents.CHAT_ERROR,
        WebhookEvents.SYSTEM_ERROR,
      ],
    })
  }, [])

  const handleSend = async (content: string) => {
    try {
      const messageId = Date.now().toString()

      // Add user message
      setMessages(prev => [...prev, {
        id: messageId,
        role: 'user',
        content,
        timestamp: Date.now(),
      }])

      // Emit message sent event
      await webhooks.emit({
        id: `msg-${messageId}`,
        type: WebhookEvents.CHAT_MESSAGE_SENT,
        data: { messageId, content },
        timestamp: Date.now(),
      })

      // Get AI response
      const response = await fetch('/api/chat', {
        method: 'POST',
        body: JSON.stringify({ message: content }),
      })

      if (!response.ok) {
        throw new Error('Chat request failed')
      }

      const data = await response.json()

      // Add assistant message
      setMessages(prev => [...prev, {
        id: data.id,
        role: 'assistant',
        content: data.message,
        timestamp: Date.now(),
      }])

      // Emit completion event
      await webhooks.emit({
        id: `comp-${data.id}`,
        type: WebhookEvents.CHAT_COMPLETION,
        data: {
          messageId: data.id,
          tokens: data.tokens,
          model: data.model,
        },
        timestamp: Date.now(),
      })
    } catch (error) {
      // Emit error event
      await webhooks.emit({
        id: `err-${Date.now()}`,
        type: WebhookEvents.CHAT_ERROR,
        data: {
          error: error.message,
          messageId: Date.now().toString(),
        },
        timestamp: Date.now(),
      })
    }
  }

  return (
    <ChatWindow
      messages={messages}
      onSendMessage={handleSend}
    />
  )
}
```

